toolArgs.file_text:
@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="Content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>

    @if (_lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private const int AutoSaveIntervalMs = 30_000;

    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private string? _lastSavedContent;
    private DateTime? _lastSavedAt;

    private string Content { get; set; } = string.Empty;

    private bool HasUnsavedChanges => Content != _lastSavedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            await _interop.InitializeAsync(_dotNetRef);

            var saved = await _interop.LoadAsync();
            Content = saved;
            _lastSavedContent = saved;

            await _interop.StartAutoSaveAsync(AutoSaveIntervalMs);
            StateHasChanged();
        }
    }

    [JSInvokable]
    public async Task OnAutoSaved()
    {
        await InvokeAsync(async () =>
        {
            await PerformSaveAsync();
            StateHasChanged();
        });
    }

    private async Task SaveNowAsync()
    {
        await PerformSaveAsync();
    }

    private async Task PerformSaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(Content);
        _lastSavedContent = Content;
        _lastSavedAt = DateTime.Now;

        await _interop.DisableUnloadGuardAsync();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        Content = string.Empty;
        _lastSavedContent = string.Empty;
        _lastSavedAt = null;

        await _interop.ClearAsync();
        await _interop.DisableUnloadGuardAsync();
    }

    private async Task OnContentChanged(ChangeEventArgs e)
    {
        Content = e.Value?.ToString() ?? string.Empty;

        if (_interop is not null && HasUnsavedChanges)
        {
            await _interop.EnableUnloadGuardAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_interop is not null)
            await _interop.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

